SELECT p.gender, p.age, a.admittime, s.stay_id, s.icu_admission, s.los, s.deathtime, ph.medication, ph.dose_given, ph.dose_given_unit, ph.dose_val_rx, ph.dose_unit_rx, ph.doses_per_24_hrs, ph.route, ph.infusion_complete, ph.completion_interval, ph.new_iv_bag_hung, ph.continued_infusion_in_other_location, ph.restart_interval, ph.site, ph.non_formulary_visual_verification, d.diagnosis_code, d.diagnosis_name, d.diagnosis_type, d.diagnosis_category, d.diagnosis_severity, d.diagnosis_mortality, percent_rank() OVER (ORDER BY ph.doses_per_24_hrs) AS percentile_rank, COUNT(CASE WHEN ph.dose_given_unit = 'mg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_mg, COUNT(CASE WHEN ph.dose_given_unit = 'ml' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_ml, COUNT(CASE WHEN ph.dose_given_unit = 'g' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_g, COUNT(CASE WHEN ph.dose_given_unit = 'mcg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_mcg, COUNT(CASE WHEN ph.dose_given_unit = 'IU' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_IU, COUNT(CASE WHEN ph.dose_given_unit = 'unit' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_unit, COUNT(CASE WHEN ph.dose_given_unit = 'units' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_units, COUNT(CASE WHEN ph.dose_given_unit = 'mg/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_mg_per_kg, COUNT(CASE WHEN ph.dose_given_unit = 'ml/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_ml_per_kg, COUNT(CASE WHEN ph.dose_given_unit = 'g/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_g_per_kg, COUNT(CASE WHEN ph.dose_given_unit = 'mcg/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_mcg_per_kg, COUNT(CASE WHEN ph.dose_given_unit = 'IU/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_IU_per_kg, COUNT(CASE WHEN ph.dose_given_unit = 'unit/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_unit_per_kg, COUNT(CASE WHEN ph.dose_given_unit = 'units/kg' THEN 1 END)::FLOAT / NULLIF(COUNT(ph.dose_given), 0) AS proportion_units_per_kg FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN stay s ON a.stay_id = s.stay_id JOIN pharmacy ph ON a.subject_id = ph.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'F' AND p.age BETWEEN 74 AND 84 AND a.admittime BETWEEN s.intime AND s.intime + interval '24 hours' AND ph.medication IS NOT NULL AND ph.dose_given IS NOT NULL AND ph.dose_given_unit IS NOT NULL AND ph.dose_val_rx IS NOT NULL AND ph.dose_unit_rx IS NOT NULL AND ph.doses_per_24_hrs IS NOT NULL AND ph.route IS NOT NULL AND ph.infusion_complete IS NOT NULL AND ph.completion_interval IS NOT NULL AND ph.new_iv_bag_hung IS NOT NULL AND ph.continued_infusion_in_other_location IS NOT NULL AND ph.restart_interval IS NOT NULL AND ph.site IS NOT NULL AND ph.non_formulary_visual_verification IS NOT NULL GROUP BY p.gender, p.age, a.admittime, s.stay_id, s.icu_admission, s.los, s.deathtime, ph.medication, ph.dose_given, ph.dose_given_unit, ph.dose_val_rx, ph.dose_unit_rx, ph.doses_per_24_hrs, ph.route, ph.infusion_complete, ph.completion_interval, ph.new_iv_bag_hung, ph.continued_infusion_in_other_location, ph.restart_interval, ph.site, ph.non_formulary_visual_verification, d.diagnosis_code, d.diagnosis_name, d.diagnosis_type, d.diagnosis_category, d.diagnosis_severity, d.diagnosis_mortality;